import * as T from './vendor/three.module.js';
export function installGeneralStore({scene,camera,colliders,pause,rewards,getNearbyPlaces=()=>[]}){
 const root=new T.Group();root.name='General Store';scene.add(root);
 const mat=c=>new T.MeshStandardMaterial({color:c,roughness:.85}),cream=mat('#eee2c5'),green=mat('#315a4a'),wood=mat('#936b45'),brass=mat('#c8a463'),paper=mat('#e8cf9b');
 const part=(g,m,x,y,z)=>{const o=new T.Mesh(g,m);o.position.set(x,y,z);o.castShadow=o.receiveShadow=true;root.add(o);return o;};
 const box=(x,y,z,w,h,d,m,solid=false)=>{const o=part(new T.BoxGeometry(w,h,d),m,x,y,z);if(solid)colliders.push({x,z,w:w/2+.25,d:d/2+.25});return o;};
 box(38,.09,-15,10,.18,10,wood);box(38,.06,-7,5,.12,6,cream);
 for(const x of [33,43])box(x,2.5,-15,.3,5,10,cream,true);box(38,2.5,-20,10,5,.3,cream,true);
 for(const x of [34.8,41.2]){box(x,.65,-10,3.3,1.3,.3,green,true);box(x,4.4,-10,3.3,1.2,.3,green);const pane=part(new T.PlaneGeometry(3.1,2.8),new T.MeshPhysicalMaterial({color:'#c7e0db',transparent:true,opacity:.2,side:T.DoubleSide,depthWrite:false}),x,2.65,-9.98);pane.castShadow=false;}
 box(38,5.1,-15,10.5,.3,10.5,green);box(38,3.8,-8.8,10,.18,2.5,green);
 for(const x of [33.3,42.7])box(x,1.85,-7.7,.14,3.7,.14,brass,true);
 function sign(text,x,y,z,w,h){const c=document.createElement('canvas');c.width=Math.round(w*160);c.height=Math.round(h*160);const ctx=c.getContext('2d');ctx.fillStyle='#315a4a';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#fff0c8';ctx.textAlign='center';ctx.textBaseline='middle';let size=c.height*.5;ctx.font=size+'px Georgia';size*=Math.min(1,c.width*.92/ctx.measureText(text).width);ctx.font=size+'px Georgia';ctx.fillText(text,c.width/2,c.height/2);const texture=new T.CanvasTexture(c);texture.colorSpace=T.SRGBColorSpace;part(new T.PlaneGeometry(w,h),new T.MeshStandardMaterial({map:texture,side:T.DoubleSide}),x,y,z);}
 sign('GENERAL STORE',38,4.65,-9.75,8,.8);
 for(const x of [34.1,41.9]){box(x,1.4,-16,1.3,2.8,6,wood,true);for(const y of [.7,1.6,2.5]){box(x,y,-16,1.5,.12,6.2,brass);for(let i=0;i<6;i++)box(x,y+.3,-18.5+i,.5,.5,.55,i%2?green:paper);}}
 box(38,1.05,-18.7,4,2.1,1,wood,true);sign('BROWSE EVERYDAY GOODS',38,2.6,-18.1,3.7,.5);
 const boardPoint={x:38,z:-16.8,name:'General Store browsing counter'},seats=[];
 const near=()=>Math.hypot(camera.position.x-boardPoint.x,camera.position.z-boardPoint.z)<1.6;
 const dialog=document.createElement('dialog');dialog.id='generalstoreMenu';dialog.setAttribute('aria-labelledby','generalstoreTitle');const title=document.createElement('h2');title.id='generalstoreTitle';title.textContent='General Store';const intro=document.createElement('p');intro.textContent='Based on @lisachandler’s original General Store: high-quality products for quick purchase, to the right of Lisa’s Coffee Shop when facing it. These sample goods and this browsing activity are prototype additions. No real purchase or payment is made.';const story=document.createElement('p');story.id='generalstoreStory';story.setAttribute('role','status');const status=document.createElement('p');status.id='generalstoreStatus';const actions=document.createElement('div');const topics=[['bottle','Reusable bottle','A refillable bottle for a day exploring Krownlandia. This is a sample product, with no purchase or inventory added.'],['notebook','Pocket notebook','A sturdy notebook for ideas, sketches and notes from your travels. This is a sample product.'],['basket','Market basket','A woven carry basket for everyday errands and visits to the garden. This is a sample product.']];for(const [id,label,text]of topics){const b=document.createElement('button');b.id='generalstoreTopic-'+id;b.textContent=label;b.onclick=()=>{if(!near())return;story.textContent=text;rewards.completeGeneralStore();refresh();};actions.append(b);}const reward=document.createElement('button');reward.id='generalstoreRewards';reward.textContent='Find store rewards';reward.onclick=()=>{rewards.guideTo('generalstore');dialog.close();};const close=document.createElement('button');close.id='generalstoreClose';close.textContent='Return to the store';close.onclick=()=>dialog.close();dialog.append(title,intro,actions,story,status,reward,close);document.body.append(dialog);const css=document.createElement('link');css.rel='stylesheet';css.href='generalstore.css';document.head.append(css);

 const nearby=document.createElement('details');nearby.id='generalstoreNearby';const nearbyTitle=document.createElement('summary');nearbyTitle.textContent='Explore nearby';const links=document.createElement('div');nearby.append(nearbyTitle,links);dialog.replaceChildren(title,intro,actions,story,status,reward,nearby,close);
 function refreshLinks(){nearby.open=false;links.replaceChildren();const places=getNearbyPlaces();nearby.hidden=!places.length;for(const p of places){const b=document.createElement('button');b.id='generalstoreWalk-'+p.id;b.textContent='Walk to '+p.name;b.onclick=()=>{if(!near()||!dialog.open)return;pause();rewards.guideToPoint({x:p.x,z:p.z,name:p.name});dialog.close();};links.append(b);}}
 function refresh(){const st=rewards.state();status.textContent=st.claims.includes('generalstore:task')?'Your store browsing reward is collected.':st.done.includes('generalstore-board')?'Product explored · 20 task points are ready at the store rewards station.':'Browse one product to unlock 20 task points.';if(!st.saved)status.textContent+=' Progress lasts for this visit only.';}
 return {seats,boardPoint,get near(){return near()},get isOpen(){return dialog.open},open(){if(!near()||dialog.open)return false;pause();refreshLinks();story.textContent='Choose a sample product to read about it.';refresh();dialog.showModal();return true;}};
}
